CREATE OR REPLACE FUNCTION get_an (_nameOfSerie VARCHAR, _lang TEXT) RETURNS TABLE ( warningId uuid, warningType VARCHAR, nameOfSeries VARCHAR, warningNumber INTEGER, year INTEGER, generalArea TEXT, locality TEXT, warningHazardTypeGeneral VARCHAR, publicationDate timestamp, cancellationDate timestamp, language TEXT, productionAgency VARCHAR, country VARCHAR, featurePartId uuid, featurePartPosition INTEGER, featurePartWarningHazardTypeDetails TEXT, featurePartInformation TEXT, featurePartDateRange TEXT, type TEXT, geom geometry ) AS $$
BEGIN
RETURN QUERY (select distinct w.id as warningId, s.type as warningType, w.name_of_series as nameOfSeries, w.warning_number as warningNumber, w.year as year, string_agg(distinct w_area.name, ',') as generalArea, string_agg(distinct locality_text.text, ',') as locality, w.warning_hazard_type_general as warningHazardTypeGeneral, w.publication_time as publicationDate, w.cancellation_date as cancellationDate, _lang as "language", w.production_agency as productionAgency, w.country as country, part.id as featurePartId, part.position as featurePartPosition, string_agg(distinct part_type.warning_hazard_type_detail, ',') as featurePartWarningHazardTypeDetails, part_text.text as featurePartInformation, string_agg(concat(part_date.date_start, ' ', part_date.time_of_day_start, '/', part_date.date_end, ' ', part_date.time_of_day_end, ''), ',') as featurePartDateRange, 'geom' as type, part_geom.geom as geom from warning_feature_part as part left join warning as w on part.warning_id=w.id left join serie as s on w.serie_id=s.id left join warning_general_area as w_area on w.id=w_area.warning_id left join warning_locality as w_locality on w.id=w_locality.warning_id left join localized_text as locality_text on w_locality.id=locality_text.parent_id and locality_text.language=_lang left join warning_feature_part_geometry as part_geom on part_geom.feature_part_id=part.id left join warning_feature_part_warning_hazard_type_details as part_type on part_type.feature_part_id = part.id left join localized_text as part_text on part_text.parent_id=part.id and part_text.language=_lang left join fixed_date_range as part_date on part_date.parent_id=part.id where w.status='PUBLISHED' and UPPER(w.name_of_series)=UPPER(_nameOfSerie) group by w.id, s.type, part.id, part_type.warning_hazard_type_detail, part_text.text, part.position, part_geom.geom order by w.id ) UNION ( select distinct w.id as warningId, s.type as warningType, w.name_of_series as nameOfSeries, w.warning_number as warningNumber, w.year as year, string_agg(distinct w_area.name, ',') as generalArea, string_agg(distinct locality_text.text, ',') as locality, w.warning_hazard_type_general as warningHazardType, w.publication_time as publicationDate, w.cancellation_date as cancellationDate, _lang as "language", w.production_agency as productionAgency, w.country as country, part.id as featurePartId, part.position as featurePartPosition, string_agg(distinct part_type.warning_hazard_type_detail, ',') as featurePartWarningType, part_text.text as featurePartInformation, string_agg(concat(part_date.date_start, ' ', part_date.time_of_day_start, '/', part_date.date_end, ' ', part_date.time_of_day_end, ''), ',') as featurePartDateRange, 'affected_area' as type, part_affectedarea.geom as geom from warning_feature_part as part left join warning as w on part.warning_id=w.id left join serie as s on w.serie_id=s.id left join warning_general_area as w_area on w.id=w_area.warning_id left join warning_locality as w_locality on w.id=w_locality.warning_id left join localized_text as locality_text on w_locality.id=locality_text.parent_id and locality_text.language=_lang inner join warning_feature_part_affected_area as part_affectedarea on part_affectedarea.feature_part_id=part.id left join warning_feature_part_warning_hazard_type_details as part_type on part_type.feature_part_id = part.id left join localized_text as part_text on part_text.parent_id=part.id and part_text.language=_lang left join fixed_date_range as part_date on part_date.parent_id=part.id where w.status='PUBLISHED' and UPPER(w.name_of_series)=UPPER(_nameOfSerie) group by w.id, s.type, part.id, part_type.warning_hazard_type_detail, part_text.text, part.position, part_affectedarea.geom order by w.id ); END; $$ LANGUAGE 'plpgsql';

CREATE OR REPLACE FUNCTION get_gr (_grType VARCHAR) RETURNS TABLE ( grId uuid, grType VARCHAR, grNumber TEXT, grActivity TEXT, grTitle TEXT, grSummary TEXT, grTemporary boolean, grCoastlineLimit boolean, grPublic boolean, grArea TEXT, grDate TEXT, grSeasonalPeriod TEXT, partId uuid, partPosition INTEGER, grPartDate TEXT, grPartSeasonalPeriod TEXT, partInformation TEXT, geom geometry, partType TEXT, grLink TEXT ) AS $$
BEGIN
RETURN QUERY select distinct gr.id as grId, gr.type as grType, gr.number_year || COALESCE('-' || gr.number_text, '') || COALESCE('-' || string_agg(distinct grAuthorityCode.authority_code, ','), '') || COALESCE('-' || gr.number_date, '') as grNumber, string_agg(distinct grActivity.activity, ',') as grActivity, gr.title as grTitle, gr.summary as grSummary, gr.is_temporary as grTemporary, gr.has_coastline_limit as grCoastlineLimit, gr.is_public as grPublic, string_agg(distinct grArea.name, ',') as grArea, string_agg(distinct concat(grDate.date_start, COALESCE('/' || grDate.date_end, '')), ',') as grDate, string_agg(distinct concat(grSeasonPeriod.day_start, '/', grSeasonPeriod.month_start, '-', grSeasonPeriod.day_end, '/', grSeasonPeriod.month_end), ',') as grSeasonalPeriod, grPart.id as partId, grPart.position as partPosition, string_agg(distinct concat(grPartDate.date_start, COALESCE('/' || grPartDate.date_end, '')), ',') as grPartDate, string_agg(distinct concat(grPartSeasonPeriod.day_start, '/', grPartSeasonPeriod.month_start, '-', grPartSeasonPeriod.day_end, '/', grPartSeasonPeriod.month_end), ',') as grPartSeasonalPeriod, grPart.information as partInformation, grPartFeature.geom as geom, string_agg(distinct grPartType.type, ',') as partType, string_agg(distinct grLink.link, ',') as grLink from georegulation_part as grPart left join georegulation as gr on gr.id = grPart.georegulation_id left join georegulation_part_type as grPartType on grPartType.part_id = grPart.id left join georegulation_activity as grActivity on grActivity.georegulation_id = gr.id left join georegulation_link as grLink on grLink.georegulation_id = gr.id left join georegulation_number_authority_code as grAuthorityCode on grAuthorityCode.georegulation_id = gr.id left join georegulation_seasonal_period as grSeasonPeriod on grSeasonPeriod.georegulation_id = gr.id left join fixed_date_range as grDate on grDate.parent_id=gr.id left join georegulation_part_feature as grPartFeature on grPartFeature.part_id = grPart.id left join georegulation_part_seasonal_period as grPartSeasonPeriod on grPartSeasonPeriod.part_id = grPart.id left join fixed_date_range as grPartDate on grPartDate.parent_id=grPart.id left join maritime_service as grService on grService.id=gr.issuing_service_id left join maritime_service_areas as grServiceArea on grService.id=grServiceArea.maritime_service_id left join area as grArea on grArea.id=grServiceArea.areas_id where gr.type=_grType group by gr.id, grPart.id, grPartFeature.geom;
END; $$ LANGUAGE 'plpgsql';
